payload.script:
$ErrorActionPreference = "Stop"

try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }

$Mode = "{{Mode}}"
$ServiceInput = @"
{{Services}}
"@
$WaitSeconds = "{{WaitSeconds}}"

function ConvertTo-PlainObject {
    param($Value)
    if ($null -eq $Value) { return $null }
    if ($Value -is [string] -or $Value -is [bool] -or $Value -is [int] -or $Value -is [long] -or $Value -is [double] -or $Value -is [decimal]) { return $Value }
    if ($Value -is [System.Collections.IDictionary]) {
        $plain = [ordered]@{}
        foreach ($key in $Value.Keys) { $plain[[string]$key] = ConvertTo-PlainObject $Value[$key] }
        return $plain
    }
    if ($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])) {
        $items = New-Object System.Collections.ArrayList
        foreach ($item in $Value) { [void]$items.Add((ConvertTo-PlainObject $item)) }
        return ,$items
    }
    $properties = $Value.PSObject.Properties | Where-Object { $_.MemberType -in @("NoteProperty", "Property") -and $_.Name -notmatch "^PS" }
    if ($properties.Count -gt 0) {
        $plain = [ordered]@{}
        foreach ($property in $properties) { $plain[$property.Name] = ConvertTo-PlainObject $property.Value }
        return $plain
    }
    return [string]$Value
}

function Split-ServiceList {
    param([string]$Text)
    if (-not $Text) { return @() }
    @($Text -split "[,;`r`n]+" | ForEach-Object { $_.Trim() } | Where-Object { $_ } | Select-Object -Unique)
}

function Get-ServiceRecord {
    param([string]$Name)
    $svc = Get-Service -Name $Name -ErrorAction SilentlyContinue
    if (-not $svc) {
        $svc = Get-Service -DisplayName $Name -ErrorAction SilentlyContinue | Select-Object -First 1
    }
    return $svc
}

function Wait-ServiceStateSafe {
    param($Service, [string]$TargetStatus, [int]$TimeoutSeconds)
    try {
        $Service.WaitForStatus([System.ServiceProcess.ServiceControllerStatus]::$TargetStatus, [TimeSpan]::FromSeconds($TimeoutSeconds))
        return $true
    } catch {
        return $false
    }
}

try {
    $validModes = @("Status", "Start", "Stop", "Restart")
    if ($validModes -notcontains $Mode) { $Mode = "Status" }
    $timeout = 30
    try { $timeout = [Math]::Max(1, [Math]::Min(300, [int]$WaitSeconds)) } catch { $timeout = 30 }

    $serviceNames = @(Split-ServiceList $ServiceInput)
    if ($serviceNames.Count -eq 0) { throw "Specify at least one service name or display name." }

    $results = @()
    foreach ($requestedName in $serviceNames) {
        $item = [ordered]@{
            requested = $requestedName
            name = $null
            display_name = $null
            mode = $Mode
            before = $null
            after = $null
            changed = $false
            success = $false
            message = ""
        }

        try {
            $service = Get-ServiceRecord -Name $requestedName
            if (-not $service) {
                $item.message = "Service not found"
                $results += [pscustomobject]$item
                continue
            }

            $item.name = $service.Name
            $item.display_name = $service.DisplayName
            $item.before = [string]$service.Status

            if ($Mode -eq "Status") {
                $item.after = [string]$service.Status
                $item.success = $true
                $item.message = "Status read"
                $results += [pscustomobject]$item
                continue
            }

            if ($Mode -eq "Start") {
                if ($service.Status -ne "Running") {
                    Start-Service -Name $service.Name -ErrorAction Stop
                    $service.Refresh()
                    [void](Wait-ServiceStateSafe -Service $service -TargetStatus "Running" -TimeoutSeconds $timeout)
                    $service.Refresh()
                    $item.changed = $true
                }
                $item.after = [string]$service.Status
                $item.success = ($service.Status -eq "Running")
                $item.message = if ($item.success) { "Service is running" } else { "Service did not reach Running state" }
                $results += [pscustomobject]$item
                continue
            }

            if ($Mode -eq "Stop") {
                if ($service.Status -ne "Stopped") {
                    Stop-Service -Name $service.Name -Force -ErrorAction Stop
                    $service.Refresh()
                    [void](Wait-ServiceStateSafe -Service $service -TargetStatus "Stopped" -TimeoutSeconds $timeout)
                    $service.Refresh()
                    $item.changed = $true
                }
                $item.after = [string]$service.Status
                $item.success = ($service.Status -eq "Stopped")
                $item.message = if ($item.success) { "Service is stopped" } else { "Service did not reach Stopped state" }
                $results += [pscustomobject]$item
                continue
            }

            if ($Mode -eq "Restart") {
                if ($service.Status -ne "Stopped") {
                    Stop-Service -Name $service.Name -Force -ErrorAction Stop
                    $service.Refresh()
                    [void](Wait-ServiceStateSafe -Service $service -TargetStatus "Stopped" -TimeoutSeconds $timeout)
                }
                Start-Service -Name $service.Name -ErrorAction Stop
                $service.Refresh()
                [void](Wait-ServiceStateSafe -Service $service -TargetStatus "Running" -TimeoutSeconds $timeout)
                $service.Refresh()
                $item.changed = $true
                $item.after = [string]$service.Status
                $item.success = ($service.Status -eq "Running")
                $item.message = if ($item.success) { "Service restarted and running" } else { "Service did not reach Running state after restart" }
                $results += [pscustomobject]$item
                continue
            }
        } catch {
            try { if ($service) { $service.Refresh(); $item.after = [string]$service.Status } } catch { }
            $item.success = $false
            $item.message = $_.Exception.Message
            $results += [pscustomobject]$item
        }
    }

    $failed = @($results | Where-Object { -not $_.success })
    $changed = @($results | Where-Object { $_.changed })
    $result = [pscustomobject][ordered]@{
        schema = "winhub.windows_service_manager.v1"
        computer_name = $env:COMPUTERNAME
        checked_at_utc = (Get-Date).ToUniversalTime().ToString("o")
        mode = $Mode
        requested_services = @($serviceNames)
        total = @($results).Count
        success_count = @($results | Where-Object { $_.success }).Count
        failed_count = @($failed).Count
        changed_count = @($changed).Count
        status = if (@($failed).Count -eq 0) { "Success" } elseif (@($results | Where-Object { $_.success }).Count -gt 0) { "Partial failure" } else { "Failed" }
        results = @($results)
    }

    ConvertTo-PlainObject $result | ConvertTo-Json -Depth 8 -Compress
    if (@($failed).Count -gt 0) { exit 2 }
}
catch {
    $errorResult = [pscustomobject][ordered]@{
        schema = "winhub.windows_service_manager.v1"
        computer_name = $env:COMPUTERNAME
        checked_at_utc = (Get-Date).ToUniversalTime().ToString("o")
        mode = $Mode
        status = "Script error"
        error = $_.Exception.Message
        results = @()
    }
    ConvertTo-PlainObject $errorResult | ConvertTo-Json -Depth 8 -Compress
    exit 1
}

[[WINHUB_REPORT title="Windows Service Manager Report"]]
{% set ns = namespace(ok=0, partial=0, failed=0, changed=0) -%}
{% for r in results -%}
{% if r.status != 'Success' or not r.data -%}
{% set ns.failed = ns.failed + 1 -%}
{% elif r.data.failed_count and r.data.failed_count > 0 -%}
{% set ns.partial = ns.partial + 1 -%}
{% else -%}
{% set ns.ok = ns.ok + 1 -%}
{% endif -%}
{% if r.data and r.data.changed_count -%}{% set ns.changed = ns.changed + r.data.changed_count -%}{% endif -%}
{% endfor %}
Windows service manager: {{ job_title }}

SUMMARY
- Total endpoints: {{ results|length }}
- OK endpoints: {{ ns.ok }}
- Partial endpoints: {{ ns.partial }}
- Failed endpoints: {{ ns.failed }}
- Changed services: {{ ns.changed }}

SERVICE RESULTS
{% for r in results if r.status == 'Success' and r.data -%}

{{ r.host }} | mode={{ r.data.mode or '-' }} | {{ r.data.status or '-' }} | success={{ r.data.success_count or 0 }}/{{ r.data.total or 0 }} | changed={{ r.data.changed_count or 0 }}
{% for s in r.data.results %}
- {{ s.requested or '-' }}{% if s.name %} ({{ s.name }}){% endif %}: {{ s.before or '-' }} -> {{ s.after or '-' }} | success={{ s.success }} | changed={{ s.changed }} | {{ s.message or '-' }}
{% endfor %}
{% else -%}
- none
{% endfor %}

FAILURES
{% for r in results if r.status != 'Success' or not r.data -%}
- {{ r.host }} | {{ r.status }} | {{ r.log }}
{% endfor %}
{% for r in results if r.status == 'Success' and r.data and r.data.results -%}
{% for s in r.data.results if not s.success -%}
- {{ r.host }} | {{ s.requested or '-' }}{% if s.name %} / {{ s.name }}{% endif %} | {{ s.message or '-' }}
{% endfor %}
{% endfor %}
[[/WINHUB_REPORT]]
